% In this notebook each cell starts a new figure, so the examples below
% call this function first to draw the two solutions in Figure 9.2 again.
function plot_solutions()
    [T, Y] = ode45(@(t, y) 0.2 * y, [0, 4], 5);
    T_euler = 0:0.1:4;
    Y_euler = 5 * 1.02 .^ (0:40);    % Euler's method with dt = 0.1
    plot(T_euler, Y_euler, T, Y, '--')
end
